#include <vector>
#include <algorithm>

class Solution {
public:
    int countHighestScoreNodes(std::vector<int>& parents) {
        int n = parents.size();
        std::vector<std::vector<int>> children(n);
        for (int i = 1; i < n; ++i) {
            children[parents[i]].push_back(i);
        }

        std::vector<long long> subtreeSize(n, 0);
        auto calcSize = [&](auto& self, int node) -> long long {
            long long sz = 1;
            for (int ch : children[node]) {
                sz += self(self, ch);
            }
            subtreeSize[node] = sz;
            return sz;
        };

        calcSize(calcSize, 0);

        long long maxScore = 0;
        int count = 0;

        for (int i = 0; i < n; ++i) {
            long long score = 1;
            long long rem = n - subtreeSize[i];
            if (rem > 0) score *= rem;
            for (int ch : children[i]) {
                score *= subtreeSize[ch];
            }
            if (score > maxScore) {
                maxScore = score;
                count = 1;
            } else if (score == maxScore) {
                count++;
            }
        }
        return count;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int countHighestScoreNodes(int[] parents) {
        int n = parents.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) {
            children.get(parents[i]).add(i);
        }

        long[] subtreeSize = new long[n];
        calcSize(0, children, subtreeSize);

        long maxScore = 0;
        int count = 0;

        for (int i = 0; i < n; i++) {
            long score = 1;
            long rem = n - subtreeSize[i];
            if (rem > 0) score *= rem;
            for (int ch : children.get(i)) {
                score *= subtreeSize[ch];
            }
            if (score > maxScore) {
                maxScore = score;
                count = 1;
            } else if (score == maxScore) {
                count++;
            }
        }
        return count;
    }

    private long calcSize(int node, List<List<Integer>> children, long[] subtreeSize) {
        long sz = 1;
        for (int ch : children.get(node)) {
            sz += calcSize(ch, children, subtreeSize);
        }
        subtreeSize[node] = sz;
        return sz;
    }
}

